"""Standalone independent economic recursion and published-output checks."""
import io, contextlib
_buffer = io.StringIO()
with contextlib.redirect_stdout(_buffer):
    exec(compile('#!/usr/bin/env python3\n"""Independent input-literal economic recursion. No file reads or production imports.\nRuns 80 years, with full first 20 ledger endpoints. Cash PV is backward recursion.\nNo production DPS inputs. This is an author cross-check, not an external opinion.\n"""\nimport json\n\nclass Fund:\n    def __init__(self, core, actual, minimum, floor1, floor2, reserve_cap):\n        self.core,self.actual,self.minimum=core,actual,minimum\n        self.floor1,self.floor2=floor1,floor2\n        self.legal=self.reserve=self.retained=0.\n        self.cap=reserve_cap\n    def recognize(self, earnings):\n        provision=min(max(0,earnings+min(0,self.legal))*.1,max(0,self.cap-self.reserve))\n        self.reserve+=provision;self.legal+=earnings-provision\n    def room(self):\n        return max(0,min(self.core-self.floor1*self.minimum,self.actual-self.floor2*self.minimum,self.legal))\n    def pay(self, desired):\n        payment=min(max(0,desired),self.room())\n        self.core-=payment;self.actual-=payment;self.legal-=payment;self.retained-=payment\n        return payment\n    def earn(self, earnings,growth):\n        self.minimum*=1+growth\n        injection=max(0,self.floor1*self.minimum-self.core-earnings,self.floor2*self.minimum-self.actual-earnings)\n        self.core+=earnings+injection;self.actual+=earnings+injection;self.retained+=earnings+injection\n        self.recognize(earnings)\n        return injection\n\ndef independent(label):\n    new,ng,inv,broe,cor,r,capg=46,.035,23,.105,.96,.105,.03\n    if label==\'core_low\':new,ng,inv,broe,cor,r=42,.02,18,.10,.965,.11\n    if label==\'core_high\':new,ng,inv,broe,cor,r=50,.045,26,.11,.955,.10\n    if label==\'higher_capital\':capg=.05\n    if label==\'dominant_cost_plus1\':r=.115\n    life=Fund(803.36,1094.210,583.271,1.35,1.8,18.0013215855)\n    casualty=Fund(120.219,159.161,73.369,1.5,2.,10.5)\n    bank=Fund(466.076,466.076,4851.049,.095,.095,9.702959099)\n    bankbook=476.701; others=137.178; otherlegal=otherreserve=0.\n    csm=734.1; treasury=78.338-7.29862537376; parentlegal=112.05; transit=0.\n    shares=19.157641995; rows=[]; payments=[]\n    for year in range(1,81):\n        scale=1.02**max(0,year-10)\n        written=new*(1+ng)**min(year-1,9)*scale\n        available=csm*1.029+written\n        earned=available*.086;csm=available-earned\n        profit=(earned+17*scale+inv*scale+.025*life.retained)*.9\n        li=life.earn(profit,capg if year<=10 else .02)\n        spare=max(0,min(life.core-1.35*life.minimum,life.actual-1.8*life.minimum)-44.322*scale)\n        life_d=life.pay((.42+min(max(year-5,0),5)*.055)*profit+(.2*spare if year>5 else 0))\n        premium=350.7*1.035**min(year,10)*scale\n        pcprofit=(premium*(1-cor)+4*scale+.025*casualty.retained)*.8\n        pi=casualty.earn(pcprofit,.035 if year<=10 else .02)\n        pcspare=max(0,min(casualty.core-1.5*casualty.minimum,casualty.actual-2*casualty.minimum)-10.22*scale)\n        pcd=casualty.pay((.35+min(max(year-5,0),5)*.07)*pcprofit+(.2*pcspare if year>5 else 0))\n        productive=min(bankbook,bank.minimum*(476.701/4851.049))\n        bankprofit=productive*broe+(bankbook-productive)*.025\n        bi=bank.earn(bankprofit,capg if year<=10 else .02)\n        bankd=bank.pay((.30+min(max(year-5,0),5)*.07)*bankprofit+(.2*max(0,bank.core-.095*bank.minimum-5) if year>5 else 0))\n        bankbook+=bankprofit+bi-bankd\n        otherprofit=others*.055\n        oi=[10,8,6,4,4][year-1] if year<=5 else 2*1.02**(year-6)\n        reserve=min(max(0,otherprofit+min(0,otherlegal))*.1,max(0,10-otherreserve))\n        otherreserve+=reserve;otherlegal+=otherprofit-reserve\n        otherd=min(max(0,otherlegal),max(0,otherprofit-others*.02))\n        others+=otherprofit+oi-otherd;otherlegal-=otherd\n        intermediary_income=bankd*.084/.9954\n        life.recognize(intermediary_income) # no capital increase: asset converts to cash\n        transit+=bankd*.084\n        life.core+=life_d;life.actual+=life_d;life.legal+=life_d;life.retained+=life_d\n        room_before=life.room()\n        indirect_requested=transit*.8/.9954\n        requests=life_d+indirect_requested\n        ratio=min(1,room_before/requests) if requests else 0\n        life_d=life.pay(life_d*ratio)\n        intermediary_gross=life.pay(indirect_requested*ratio)\n        intermediary=intermediary_gross*.9954;transit-=intermediary\n        declared=life_d*.945+pcd*.9955+bankd*.4956+intermediary+otherd\n        parentprofit=treasury*.025-2.3*scale-.035*26.985\n        injections=li*.945+pi*.9955+bi*.5796+oi\n        treasury+=declared+parentprofit-injections\n        parentlegal+=declared+parentprofit\n        target=2.7*1.02**(year-1)*shares if year<=5 else max(0,declared+parentprofit-injections)+.2*max(0,treasury-20*scale)\n        # These independently checked paths need no incremental parent financing.\n        assert treasury>=20*scale\n        distribution=min(target,treasury-20*scale,parentlegal)\n        treasury-=distribution;parentlegal-=distribution\n        payments.append(distribution/shares)\n        rows.append(dict(year=year,csm=csm,life_core=life.core,life_actual=life.actual,life_min=life.minimum,life_legal=life.legal,life_reserve=life.reserve,bank_cet1=bank.core,bank_rwa=bank.minimum,bank_common_equity=bankbook,bank_legal=bank.legal,bank_reserve=bank.reserve,parent_cash=treasury,parent_legal=parentlegal,parent_declared=declared,indirect_bank_up=intermediary,indirect_bank_cash=transit,holder_pre_payment_capacity=room_before,dps=distribution/shares))\n    value=payments[-1]*1.02/(r-.02)\n    for payment in reversed(payments):value=(value+payment)/(1+r)\n    return {\'value\':value,\'first20\':rows[:20],\'year80\':rows[-1]}\n\nif __name__==\'__main__\':\n    print(json.dumps({name:independent(name) for name in [\'base\',\'core_low\',\'core_high\',\'higher_capital\',\'dominant_cost_plus1\']},indent=2))\n', __file__, "exec"), {"__file__": __file__, "__name__": "__main__"})
print(_buffer.getvalue())
exec(compile("from pathlib import Path\nimport json\nfrom decimal import Decimal as D,getcontext\ngetcontext().prec=40\np=str(Path(__file__).resolve().parent)+'/'\no=json.load(open(p+'2026-Q3-output.json'))['cases'];a=json.loads(_AUTHOR_JSON);errors=[];count=0\nfor name,v in a.items():\n key='sensitivity_cost_plus1' if name=='dominant_cost_plus1' else name\n assert abs(v['value']-o[key]['value'])<1e-9\n for row in v['first20']+[v['year80']]:\n  target=o[key]['rows'][row['year']-1]\n  for k,x in row.items():\n   if k in target:errors.append(abs(x-target[k]));count+=1\nassert max(errors)<1e-7\n# Independently reconstruct first-year economic inputs, legal/capital capped joint flows.\nrelease=(D('734.1')*D('1.029')+46)*D('.086');lp=(release+40)*D('.9')\npc=(D('350.7')*D('1.035')*D('.04')+4)*D('.8');bank=D('476.701')*D('.105')\nbr=bank*D('.3');transit=br*D('.084');gross=transit/D('.9954');insurance=lp*D('.42')\ncapital=min(D('803.36')+lp-D('1.35')*D('583.271')*D('1.03'),D('1094.210')+lp-D('1.8')*D('583.271')*D('1.03'))\nlegal=lp*D('.9')+gross*D('.9');want=insurance+gross*D('.8');joint=min(want,capital,legal);weight=joint/want\nlr=insurance*weight;ind=transit*D('.8')*weight\ndeclared=lr*D('.945')+pc*D('.35')*D('.9955')+br*D('.4956')+ind+D('137.178')*D('.035')\ncash=D('78.338')-D('7.29862537376');own=cash*D('.025')-D('2.3')-D('26.985')*D('.035');div=D('19.157641995')*D('2.7')\nexpected={'life_profit':lp,'pc_profit':pc,'bank_profit':bank,'parent_declared':declared,'parent_cash':cash+declared+own-10-div,'parent_legal':D('112.050')+declared+own-div,'indirect_bank_up':ind}\nfor k,v in expected.items():assert abs(float(v)-o['base']['rows'][0][k])<1e-9,(k,v)\n# Every production scenario must maintain the common insurance capital floor after BOTH payment paths.\nyears=0\nfor key,c in o.items():\n prev_transit=0\n for r in c['rows']:\n  assert r['life_core']>=1.35*r['life_min']-1e-7 and r['life_actual']>=1.8*r['life_min']-1e-7\n  assert abs(prev_transit+r['indirect_bank_received']-r['indirect_bank_up']-r['indirect_bank_cash'])<1e-7\n  assert r['indirect_bank_cash']>=-1e-8\n  prev_transit=r['indirect_bank_cash'];years+=1\n# Independent auxiliary cohort annuity first year, no CSM addition.\nfor name,inv,ng in [('ev_bridge_low',D('.035'),D('.02')),('ev_bridge_high',D('.0375'),D('.045'))]:\n drop=(D('.04')-inv)/D('.005');rate=D('.085');vif=D('541.854')-10-D('150.712')*drop\n cashprofit=vif*rate/(1-(1+rate)**-30)+D(34)*(1-D('.16844')*drop)*(1+ng)*rate/(1-(1+rate)**-15)+(D('428.985')-D('476.701')*D('.084'))*inv\n assert abs(float(cashprofit/D('.945'))-o[name]['rows'][0]['life_profit'])<1e-9\nprint(json.dumps({'fresh_author_literal_fields_compared':count,'max_absolute_error':max(errors),'own_first_year_decimal_fields':len(expected),'all_scenario_capital_transit_years':years,'own_auxiliary_cohort_endpoints':2},indent=2))\n", __file__, "exec"), {"__file__": __file__, "__name__": "__main__", "_AUTHOR_JSON": _buffer.getvalue()})
